const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={view:"dashboard",brand:"all",records:[],dashboard:null,businesses:[],search:"",status:"all",archived:false,current:null,portalLinks:{}};
const labels={all:"All businesses",wbm:"Weddings By Mark",ivory:"Ivory Digital"};
const titles={dashboard:"Dashboard",enquiries:"New enquiries",weddings:"Wedding bookings",projects:"Ivory Digital projects",calendar:"Calendar",workflows:"Things to do",invoices:"Payments & invoices",documents:"All files",packages:"Packages & pricing",communications:"Email templates",settings:"Business settings"};
const subtitles={dashboard:"Here's what needs your attention today.",enquiries:"Start here: open an enquiry, check the details and send the package quote.",weddings:"Every confirmed couple and wedding date in one place.",projects:"Website clients, services and project milestones.",calendar:"Wedding dates and project deadlines at a glance.",workflows:"Only the practical jobs that need your attention.",invoices:"Record bank transfers and see every outstanding balance.",documents:"Contracts, forms, questionnaires and attachments.",packages:"Wedding packages, deposits, add-ons and package eligibility.",communications:"Edit and preview the messages your clients receive.",settings:"Separate branding, bank and invoice details for both businesses."};
const statuses=["enquiry","quoted","confirmed","in_progress","completed","cancelled"];

function esc(v=""){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function attr(v=""){return esc(v)}
function fmtDate(v){if(!v)return "No date set";return new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"short",year:"numeric"}).format(new Date(v.slice(0,10)+"T12:00:00"))}
function fmtDateTime(v){if(!v)return "No date";return new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(v))}
function money(v){return new Intl.NumberFormat("en-GB",{style:"currency",currency:"GBP",minimumFractionDigits:2}).format(Number(v||0))}
function bytes(v){return Number(v||0)<1048576?`${Math.max(1,Math.round(Number(v||0)/1024))} KB`:`${(Number(v)/1048576).toFixed(1)} MB`}
function initials(r){return (r.title||"?").split(/\s+|&/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase()}
function statusText(s){return String(s||"").replaceAll("_"," ")}
function statusClass(s){return /due|quoted|enquiry|unpaid|part_paid/.test(s)?"warning":/cancelled/.test(s)?"danger":/paid|completed|confirmed/.test(s)?"success":""}
function dashboardGreeting(){let hour;try{const parts=new Intl.DateTimeFormat("en-GB",{timeZone:"Europe/London",hour:"2-digit",hourCycle:"h23"}).formatToParts(new Date());hour=Number(parts.find(part=>part.type==="hour")?.value)}catch(_){hour=new Date().getHours()}const greeting=hour<12?"Good morning":hour<18?"Good afternoon":"Good evening";return `${greeting}, Mark`}
function venueDirections(r){return window.WBMVenues?.mapsUrl(r.venue_place_id,r.venue_lat,r.venue_lng,r.venue_address||r.venue_or_project)||""}
function value(id){return $(id)?.value??""}
function nullable(v){const x=String(v??"").trim();return x||null}
async function api(path,options={}){const res=await fetch(path,{credentials:"same-origin",headers:{...(options.body instanceof FormData?{}:{"Content-Type":"application/json"}),...(options.headers||{})},...options});if(res.status===401){showLogin();throw new Error("Please sign in")};if(res.status===204)return null;const data=await res.json().catch(()=>({}));if(!res.ok){const detail=Array.isArray(data.detail)?data.detail.map(x=>x.msg).join(", "):data.detail;throw new Error(detail||"Something went wrong")}return data}
function toast(text,type=""){const el=$("#toast");el.textContent=text;el.className=`toast ${type}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.add("hidden"),3000)}
function showLogin(){$("#app").classList.add("hidden");$("#login").classList.remove("hidden")}
function showApp(){$("#login").classList.add("hidden");$("#app").classList.remove("hidden")}

async function init(){bind();try{const me=await api("/api/auth/me");$("#login-email").value=me.email;showApp();await loadAll()}catch(e){showLogin()}}
function bind(){
  $("#login-form").onsubmit=async e=>{e.preventDefault();$("#login-error").textContent="";try{await api("/api/auth/login",{method:"POST",body:JSON.stringify({email:value("#login-email"),password:value("#login-password")})});showApp();await loadAll()}catch(err){$("#login-error").textContent=err.message}};
  $("#logout").onclick=async()=>{await api("/api/auth/logout",{method:"POST"});showLogin()};
  $("#brand-toggle").onclick=()=>$("#brand-menu").classList.toggle("hidden");
  $$("#brand-menu button").forEach(b=>b.onclick=()=>{state.brand=b.dataset.brand;$("#brand-label").textContent=labels[state.brand];$("#brand-dot").className=`dot ${state.brand}`;$("#brand-menu").classList.add("hidden");render()});
  $$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
  $("#open-menu").onclick=$("#mobile-more").onclick=()=>toggleMenu(true);$("#close-menu").onclick=$("#scrim").onclick=()=>toggleMenu(false);
  $("#add-record").onclick=$("#mobile-add").onclick=()=>openRecordModal();
  $("#modal-overlay").onclick=closeModal;$("#drawer-overlay").onclick=closeDrawer;
  $("#search").oninput=e=>{state.search=e.target.value.toLowerCase();render()};
  $("#attention-button").onclick=async()=>navigate("enquiries");
  document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeModal();closeDrawer();toggleMenu(false)}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();$("#search").focus()}});
}
function toggleMenu(on){$("#sidebar").classList.toggle("open",on);$("#scrim").classList.toggle("hidden",!on)}
async function navigate(view){state.view=view;state.status="all";toggleMenu(false);if(state.archived&&!['enquiries','weddings','projects'].includes(view)){state.archived=false;await refresh()}$$('[data-view]').forEach(b=>b.classList.toggle("active",b.dataset.view===view));render()}
function updateAttention(){const count=Number(state.dashboard?.open_enquiries||0);$("#attention-count").textContent=count;$("#attention-button").classList.toggle("hidden",count===0)}
async function loadAll(){const [dash,records,businesses]=await Promise.all([api("/api/dashboard"),api("/api/bookings"),api("/api/businesses")]);state.dashboard=dash;state.records=records;state.businesses=businesses;updateAttention();render()}
async function refresh(){const [dash,records]=await Promise.all([api("/api/dashboard"),api(`/api/bookings?archived=${state.archived}`)]);state.dashboard=dash;state.records=records;updateAttention()}
function filtered(items=state.records){return items.filter(r=>(state.brand==="all"||r.brand===state.brand)&&(!state.search||`${r.title} ${r.venue_or_project||""} ${r.package_name||""} ${r.client?.email||""}`.toLowerCase().includes(state.search))&&(state.status==="all"||r.status===state.status))}

function render(){
  $("#page-eyebrow").textContent=labels[state.brand].toUpperCase();$("#page-title").textContent=state.view==="dashboard"?dashboardGreeting():titles[state.view];$("#page-subtitle").textContent=subtitles[state.view];
  const digital=state.view==="projects"||state.brand==="ivory";$("#add-record").innerHTML=`<span>＋</span> Add ${digital?"project":"booking"}`;
  if(state.view==="dashboard")renderDashboard();else if(["enquiries","weddings","projects"].includes(state.view))renderRecords();else if(state.view==="calendar")renderCalendar();else if(state.view==="workflows")renderWorkflows();else if(state.view==="invoices")renderInvoices();else if(state.view==="documents")renderDocuments();else if(state.view==="packages")renderPackages();else if(state.view==="communications")renderCommunicationsV2();else renderSettings();
}
function recordRow(r){return `<button class="record-row" data-record="${r.id}"><span class="record-avatar ${r.brand}">${esc(initials(r))}</span><span class="record-main"><strong>${esc(r.title)}</strong><small>${esc(r.venue_or_project||r.client.email)}</small></span><span class="record-date">${esc(fmtDate(r.event_date))}</span><span class="status ${statusClass(r.status)}">${esc(statusText(r.status))}</span><span class="more">•••</span></button>`}
function taskRow(t,compact=false){return `<div class="task-row ${t.completed?"done":""}" data-task="${t.id}"><button class="task-toggle" data-action="toggle-task" aria-label="Toggle task">${t.completed?"✓":""}</button><button class="task-main" data-record="${t.booking_id}"><strong>${esc(t.title)}</strong><small>${esc(t.booking_title||"")}</small></button><time>${t.due_at?esc(fmtDate(t.due_at)):"No date"}</time>${compact?"":`<button class="mini" data-action="edit-task">Edit</button><button class="mini danger-text" data-action="delete-task">Delete</button>`}</div>`}
function wireRecords(root=$("#content")){$$('[data-record]',root).forEach(b=>b.onclick=e=>{if(e.target.closest('[data-action]'))return;openDrawer(b.dataset.record)});$$('[data-jump]',root).forEach(b=>b.onclick=()=>navigate(b.dataset.jump))}

function renderDashboard(){const d=state.dashboard||{};const upcoming=filtered(d.upcoming||[]);const tasks=(d.tasks||[]).filter(t=>state.brand==="all"||state.records.find(r=>r.id===t.booking_id)?.brand===state.brand);$("#content").innerHTML=`
  <section class="focus-strip"><button class="focus-card primary-focus" data-jump="enquiries"><span><strong>Enquiries ready for you</strong><span>Start here: check the couple and send their package quote.</span></span><b class="focus-number">${d.open_enquiries||0}</b></button><button class="focus-card" data-jump="workflows"><span><strong>Things to do</strong><span>Only jobs that need your attention</span></span><b class="focus-number">${d.open_tasks||0}</b></button><button class="focus-card" data-jump="calendar"><span><strong>Upcoming dates</strong><span>Your next booked events</span></span><b class="focus-number">${upcoming.length}</b></button></section>
  <section class="stats">
    <button class="stat-card" data-jump="${state.brand==="ivory"?"projects":"weddings"}"><i class="metric teal">□</i><span><strong>${state.brand==="ivory"?filtered().length:d.confirmed||0}</strong><small>${state.brand==="ivory"?"Active projects":"Confirmed weddings"}</small></span><em>Open records</em></button>
    <button class="stat-card" data-jump="weddings"><i class="metric blue">♙</i><span><strong>${d.open_enquiries||0}</strong><small>Open enquiries</small></span><em>Ready to follow up</em></button>
    <button class="stat-card" data-jump="invoices"><i class="metric amber">£</i><span><strong>${money(d.outstanding)}</strong><small>Outstanding</small></span><em>View invoices</em></button>
  </section>
  <section class="dash-grid"><article class="panel"><div class="panel-title"><div><h2>${state.brand==="ivory"?"Active projects":"Upcoming dates"}</h2><p>Your next bookings and deadlines</p></div><button data-jump="calendar">View all</button></div>${upcoming.length?upcoming.slice(0,7).map(recordRow).join(""):`<div class="empty"><strong>No upcoming records</strong>Add a booking or project to get started.</div>`}</article>
  <article class="panel"><div class="panel-title"><div><h2>Open tasks · ${d.open_tasks||0}</h2><p>Tap the circle to complete</p></div><button data-jump="workflows">View all</button></div>${tasks.length?tasks.slice(0,7).map(t=>taskRow(t,true)).join(""):`<div class="empty"><strong>You're all caught up</strong>No open tasks.</div>`}</article></section>`;
  wireRecords();$$('[data-action="toggle-task"]',$("#content")).forEach(b=>b.onclick=()=>toggleTask(b.closest("[data-task]")));
}

function renderRecords(){const kind=state.view==="projects"?"digital":"wedding",openEnquiries=state.view==="enquiries",confirmedWeddings=state.view==="weddings";const rows=filtered().filter(r=>r.kind===kind&&(!openEnquiries||["enquiry","quoted"].includes(r.status))&&(!confirmedWeddings||!["enquiry","quoted"].includes(r.status)));const availableStatuses=openEnquiries?["all","enquiry","quoted"]:confirmedWeddings?["all","confirmed","in_progress","completed","cancelled"]:["all",...statuses];$("#content").innerHTML=`<article class="panel"><div class="tools"><div class="filter-pills">${availableStatuses.map(s=>`<button data-status="${s}" class="${state.status===s?"active":""}">${s==="all"?(openEnquiries?"All open enquiries":confirmedWeddings?"All wedding bookings":"All"):statusText(s)}</button>`).join("")}</div><label class="archive-switch"><input id="archive-toggle" type="checkbox" ${state.archived?"checked":""}> Archived</label></div><div class="table-wrap"><div class="table"><div class="table-head"><span>Client</span><span>Venue / project</span><span>Date</span><span>Status</span><span>Value</span></div>${rows.map(r=>`<button class="table-row" data-record="${r.id}"><span class="client-cell"><i class="client-avatar ${r.brand}">${esc(initials(r))}</i><strong>${esc(r.title)}</strong></span><span>${esc(r.venue_or_project||"Not set")}</span><span>${esc(fmtDate(r.event_date))}</span><span class="status ${statusClass(r.status)}">${esc(statusText(r.status))}</span><strong>${money(r.quoted_total)}</strong></button>`).join("")}</div>${rows.length?"":`<div class="empty"><strong>${openEnquiries?"No enquiries waiting":"No wedding bookings found"}</strong>${openEnquiries?"New website enquiries will appear here automatically.":"Confirmed weddings appear here after the couple accepts their quote."}</div>`}</div></article>`;
  $$('[data-status]').forEach(b=>b.onclick=()=>{state.status=b.dataset.status;renderRecords()});$("#archive-toggle").onchange=async e=>{state.archived=e.target.checked;await refresh();renderRecords()};wireRecords();
}

function renderCalendar(){const rows=filtered().filter(r=>r.event_date).sort((a,b)=>a.event_date.localeCompare(b.event_date));const groups={};rows.forEach(r=>{const key=new Intl.DateTimeFormat("en-GB",{month:"long",year:"numeric"}).format(new Date(r.event_date+"T12:00:00"));(groups[key]??=[]).push(r)});$("#content").innerHTML=Object.keys(groups).length?`<div class="calendar-list">${Object.entries(groups).map(([month,items])=>`<section class="panel month"><div class="panel-title"><div><h2>${esc(month)}</h2><p>${items.length} dated record${items.length===1?"":"s"}</p></div></div>${items.map(r=>`<button class="calendar-row" data-record="${r.id}"><time><strong>${r.event_date.slice(8,10)}</strong><small>${new Intl.DateTimeFormat("en-GB",{weekday:"short"}).format(new Date(r.event_date+"T12:00:00"))}</small></time><span><strong>${esc(r.title)}</strong><small>${esc(r.venue_or_project||r.package_name||"")}</small></span><i class="brand-badge ${r.brand}">${esc(labels[r.brand])}</i></button>`).join("")}</section>`).join("")}</div>`:`<div class="panel empty"><strong>No dated records</strong>Add a date to a booking or project and it will appear here.</div>`;wireRecords()}

function weddingWorkflowGuide(paused=false){const badge=paused?`<em class="workflow-paused">MANUAL ONLY</em>`:"";return `<section class="simple-workflow ${paused?"paused":""}"><header><div><strong>${paused?"Imported Studio Ninja wedding":"Your simple wedding workflow"}</strong><span>${paused?"Visible everywhere, with all new-system automatic emails paused.":"Only the actions and reminders you actually use."}</span></div>${badge}</header><div class="workflow-grid"><article><b>1</b><span><strong>Quote</strong><small>You send the quote. If it is not accepted, a polite check follows after 1 day and a final check after 9 days.</small></span></article><article><b>2</b><span><strong>Booking accepted</strong><small>Confirmation and invoice are sent. The couple completes their booking form and contract. If nothing is paid, one booking-fee reminder goes the next day.</small></span></article><article><b>3</b><span><strong>Before the wedding</strong><small>A friendly check-in goes 120 days before, followed by the final-details questionnaire 30 days before.</small></span></article><article><b>4</b><span><strong>Final balance</strong><small>Reminders go 7 days before, 1 day before, then 2 days overdue and every 2 days until the invoice is paid.</small></span></article></div>${paused?`<p>Studio Ninja remains responsible for this couple's existing messages. You can still add a private manual task below.</p>`:""}</section>`}
async function renderWorkflows(){const token=state.view;$("#content").innerHTML=`<div class="panel loading">Loading workflows…</div>`;try{const qs=state.brand==="all"?"":`?brand=${state.brand}`;const tasks=await api(`/api/tasks${qs}`);if(state.view!==token)return;const visible=tasks.filter(t=>!state.search||`${t.title} ${t.booking_title}`.toLowerCase().includes(state.search));const guide=state.brand==="ivory"?"":weddingWorkflowGuide(false);$("#content").innerHTML=`${guide}<article class="panel"><div class="panel-title"><div><h2>Things for you to do</h2><p>${visible.filter(t=>!t.completed).length} open · ${visible.filter(t=>t.completed).length} complete · imported Studio Ninja clutter is hidden</p></div></div><div class="task-list">${visible.map(t=>taskRow(t)).join("")||`<div class="empty"><strong>Nothing needs doing</strong>Automatic emails and payment reminders do not create extra tasks here.</div>`}</div></article>`;wireTaskActions($("#content"))}catch(e){showError(e)}}
function wireTaskActions(root){$$('[data-action="toggle-task"]',root).forEach(b=>b.onclick=()=>toggleTask(b.closest("[data-task]")));$$('[data-action="edit-task"]',root).forEach(b=>b.onclick=()=>editTask(b.closest("[data-task]").dataset.task));$$('[data-action="delete-task"]',root).forEach(b=>b.onclick=()=>deleteTask(b.closest("[data-task]").dataset.task));$$('[data-record]',root).forEach(b=>b.onclick=()=>openDrawer(b.dataset.record))}
async function toggleTask(row){try{const done=!row.classList.contains("done");await api(`/api/tasks/${row.dataset.task}`,{method:"PATCH",body:JSON.stringify({completed:done})});await refresh();toast(done?"Task completed":"Task reopened");state.current?await openDrawer(state.current.id,state.currentTab||"Workflow"):render()}catch(e){toast(e.message,"error")}}
async function editTask(id){const tasks=await api("/api/tasks");const t=tasks.find(x=>x.id===id);if(!t)return;showModal("Edit task",`<label class="full">Task<input id="task-title" value="${attr(t.title)}" required></label><label class="full">Due date and time<input id="task-due" type="datetime-local" value="${t.due_at?attr(t.due_at.slice(0,16)):""}"></label>`,async()=>{await api(`/api/tasks/${id}`,{method:"PATCH",body:JSON.stringify({title:value("#task-title").trim(),due_at:nullable(value("#task-due"))})});closeModal();await refresh();toast("Task updated");state.current?openDrawer(state.current.id,"Workflow"):render()})}
async function deleteTask(id){if(!confirm("Delete this task?"))return;try{await api(`/api/tasks/${id}`,{method:"DELETE"});await refresh();toast("Task deleted");state.current?openDrawer(state.current.id,"Workflow"):render()}catch(e){toast(e.message,"error")}}

async function renderInvoices(){const view=state.view;$("#content").innerHTML=`<div class="panel loading">Loading invoices…</div>`;try{const qs=state.brand==="all"?"":`?brand=${state.brand}`;let rows=await api(`/api/invoices${qs}`);rows=rows.filter(i=>!state.search||`${i.number} ${i.legacy_number||""} ${i.client}`.toLowerCase().includes(state.search));if(state.view!==view)return;$("#content").innerHTML=`<article class="panel"><div class="panel-title"><div><h2>Invoice register</h2><p>${rows.length} invoice${rows.length===1?"":"s"} · independent WBM and Ivory Digital sequences</p></div></div><div class="table-wrap"><div class="table invoices"><div class="table-head"><span>Invoice</span><span>Client</span><span>Brand</span><span>Issued</span><span>Balance</span><span>Status</span><span>Files</span></div>${rows.map(i=>`<div class="table-row"><strong>${esc(i.number)}${i.legacy_number?`<small class="legacy-ref">Studio Ninja ${esc(i.legacy_number)}</small>`:""}</strong><button class="link-button" data-record="${i.booking_id}">${esc(i.client||"")}</button><span class="brand-badge ${i.brand}">${esc(labels[i.brand])}</span><span>${esc(fmtDate(i.issue_date))}</span><strong>${money(i.balance)}</strong><span class="status ${statusClass(i.status)}">${esc(statusText(i.status))}</span><span class="file-actions"><a href="/api/invoices/${i.id}/pdf" title="Download invoice">PDF</a>${i.paid>0?`<a href="/api/invoices/${i.id}/receipt.pdf" title="Download receipt">Receipt</a>`:""}</span></div>`).join("")}</div>${rows.length?"":`<div class="empty"><strong>No invoices yet</strong>Create one from a record's Finance tab.</div>`}</div></article>`;wireRecords()}catch(e){showError(e)}}

async function renderDocuments(){const view=state.view;$("#content").innerHTML=`<div class="panel loading">Loading documents…</div>`;try{const qs=state.brand==="all"?"":`?brand=${state.brand}`;let rows=await api(`/api/documents${qs}`);rows=rows.filter(d=>!state.search||`${d.original_name} ${d.booking_title} ${d.category}`.toLowerCase().includes(state.search));if(state.view!==view)return;$("#content").innerHTML=`<article class="panel"><div class="panel-title"><div><h2>Document library</h2><p>Everything remains attached to its correct record</p></div></div><div class="document-list">${rows.map(d=>documentRow(d,true)).join("")||`<div class="empty"><strong>No documents uploaded</strong>Open a record to upload contracts, forms or images.</div>`}</div></article>`;wireDocumentActions($("#content"))}catch(e){showError(e)}}
function documentRow(d,showRecord=false){return `<div class="document-row ${d.source_system==="studio_ninja"?"legacy-document":""}" data-document="${d.id}"><i>▤</i><span><strong>${esc(d.original_name)}</strong><small>${esc(statusText(d.legacy_document_type||d.category))} · ${bytes(d.size_bytes)}${d.document_date?` · ${esc(fmtDate(d.document_date))}`:""}${showRecord?` · ${esc(d.booking_title)}`:""}</small>${d.source_system==="studio_ninja"?`<em>Original Studio Ninja document${d.is_client_visible?" · visible to couple":""}</em>`:""}</span>${showRecord?`<button class="link-button" data-record="${d.booking_id}">Open record</button>`:""}<a class="secondary small-button" href="/api/documents/${d.id}">Download</a>${d.source_system==="studio_ninja"?"":`<button class="mini danger-text" data-action="delete-document">Delete</button>`}</div>`}
function wireDocumentActions(root){$$('[data-action="delete-document"]',root).forEach(b=>b.onclick=()=>deleteDocument(b.closest("[data-document]").dataset.document));$$('[data-record]',root).forEach(b=>b.onclick=()=>openDrawer(b.dataset.record))}
async function deleteDocument(id){if(!confirm("Delete this document from the booking system?"))return;try{await api(`/api/documents/${id}`,{method:"DELETE"});toast("Document deleted");state.current?openDrawer(state.current.id,"Documents"):renderDocuments()}catch(e){toast(e.message,"error")}}

async function renderPackages(){
  const view=state.view;$("#content").innerHTML=`<div class="panel loading">Loading packages…</div>`;
  try{
    const d=await api("/api/catalog?brand=wbm&include_inactive=true");if(state.view!==view)return;
    const packageNames=Object.fromEntries(d.packages.map(x=>[x.code,x.name.replace(/ Package.*$/,"")]));
    $("#content").innerHTML=`<section class="comm-status"><div class="ready"><strong>Website enquiry form ready</strong><span>Every submission automatically creates a new wedding enquiry here.</span></div><a class="secondary embed-preview" href="/enquiry" target="_blank" rel="noopener">Preview form</a><button id="copy-enquiry-embed" class="secondary">Copy website embed code</button></section><div class="catalog-columns"><section class="panel"><div class="panel-title"><div><h2>Wedding packages</h2><p>These appear in price order in the couple's wedding quote</p></div><button id="new-package" class="primary">＋ Add package</button></div><div class="catalog-list">${d.packages.map(p=>`<article class="catalog-card ${p.is_active?"":"inactive"}"><header><div><strong>${esc(p.name)}</strong><span class="status ${p.is_active?"success":""}">${p.is_active?"Active":"Hidden"}</span></div><div class="catalog-actions"><button class="mini" data-package="${p.id}">Edit</button><button class="mini danger-text" data-delete-package="${p.id}">Delete</button></div></header><p>${esc(p.description)}</p><div class="catalog-meta"><span>Deposit ${money(p.deposit_amount)} · position ${p.display_order}</span><strong class="catalog-price">${money(p.price)}</strong></div></article>`).join("")}</div></section><section class="panel"><div class="panel-title"><div><h2>Add-ons</h2><p>Eligibility controls which package shows each extra</p></div><button id="new-addon" class="primary">＋ Add extra</button></div><div class="catalog-list">${d.addons.map(a=>`<article class="catalog-card ${a.is_active?"":"inactive"}"><header><div><strong>${esc(a.name)}</strong><span class="status ${a.is_active?"success":""}">${a.is_active?"Active":"Hidden"}</span></div><div class="catalog-actions"><button class="mini" data-addon="${a.id}">Edit</button><button class="mini danger-text" data-delete-addon="${a.id}">Delete</button></div></header><p>${esc(a.description)}</p><div class="catalog-meta"><div class="catalog-eligibility">${a.eligible_package_codes.map(code=>`<i>${esc(packageNames[code]||code)}</i>`).join("")||"All packages"}</div><strong class="catalog-price">${money(a.price)}</strong></div></article>`).join("")}</div></section></div>`;
    $$('[data-package]').forEach(b=>b.onclick=()=>editPackage(d.packages.find(x=>x.id===b.dataset.package)));
    $$('[data-addon]').forEach(b=>b.onclick=()=>editAddon(d.addons.find(x=>x.id===b.dataset.addon),d.packages));
    $$('[data-delete-package]').forEach(b=>b.onclick=()=>deleteCatalogItem("package",d.packages.find(x=>x.id===b.dataset.deletePackage)));
    $$('[data-delete-addon]').forEach(b=>b.onclick=()=>deleteCatalogItem("addon",d.addons.find(x=>x.id===b.dataset.deleteAddon)));
    $("#new-package").onclick=()=>newPackage(d.packages);
    $("#new-addon").onclick=()=>newAddon(d.packages,d.addons);
    $("#copy-enquiry-embed").onclick=async()=>{const origin=location.origin;const code=`<iframe id="wbm-enquiry-form" src="${origin}/enquiry" style="width:100%;max-width:1040px;height:1600px;border:0" loading="lazy" title="Weddings By Mark enquiry form"></iframe>\n<script data-iframe-id="wbm-enquiry-form" src="${origin}/static/enquiry-embed.js"></script>`;await navigator.clipboard.writeText(code);toast("Website embed code copied")};
  }catch(e){showError(e)}
}
async function deleteCatalogItem(type,item){if(!item)return;const label=type==="package"?"package":"add-on";if(!confirm(`Delete ${label} "${item.name}"?\n\nIt will be removed from future quotes. Items already used on accepted quotes or invoices are protected.`))return;try{await api(`/api/catalog/${type==="package"?"packages":"addons"}/${item.id}`,{method:"DELETE"});toast(`${type==="package"?"Package":"Add-on"} deleted`);renderPackages()}catch(e){toast(e.message,"error")}}
function editPackage(p){showModal(`Edit ${p.name}`,`<label class="full">Package name<input id="catalog-name" value="${attr(p.name)}" required></label><label>Price<input id="catalog-price" type="number" min="0" step="0.01" value="${p.price}" required></label><label>Booking fee / deposit<input id="catalog-deposit" type="number" min="0" step="0.01" value="${p.deposit_amount}" required></label><label>Display position<input id="catalog-order" type="number" min="0" value="${p.display_order}" required></label><label>Visibility<select id="catalog-active"><option value="true" ${p.is_active?"selected":""}>Active</option><option value="false" ${p.is_active?"":"selected"}>Hidden</option></select></label><label class="full">Full package wording<textarea id="catalog-description" rows="15" required>${esc(p.description)}</textarea></label>`,async()=>{await api(`/api/catalog/packages/${p.id}`,{method:"PATCH",body:JSON.stringify({name:value("#catalog-name").trim(),price:Number(value("#catalog-price")),deposit_amount:Number(value("#catalog-deposit")),display_order:Number(value("#catalog-order")),is_active:value("#catalog-active")==="true",description:value("#catalog-description").trim()})});closeModal();toast("Package saved");renderPackages()},"Changes appear on future client quotes. Accepted quotes keep their original wording and price.")}
function editAddon(a,packages){const checks=packages.map(p=>`<label class="check-option"><input type="checkbox" name="eligible" value="${p.code}" ${a.eligible_package_codes.includes(p.code)?"checked":""}><span>${esc(p.name)}</span></label>`).join("");showModal(`Edit ${a.name}`,`<label class="full">Add-on name<input id="catalog-name" value="${attr(a.name)}" required></label><label>Price<input id="catalog-price" type="number" min="0" step="0.01" value="${a.price}" required></label><label>Display position<input id="catalog-order" type="number" min="0" value="${a.display_order}" required></label><label>Visibility<select id="catalog-active"><option value="true" ${a.is_active?"selected":""}>Active</option><option value="false" ${a.is_active?"":"selected"}>Hidden</option></select></label><label class="full">Description<textarea id="catalog-description" rows="5" required>${esc(a.description)}</textarea></label><div class="full"><div class="section-label">AVAILABLE WITH</div><div class="check-grid">${checks}</div></div>`,async()=>{await api(`/api/catalog/addons/${a.id}`,{method:"PATCH",body:JSON.stringify({name:value("#catalog-name").trim(),price:Number(value("#catalog-price")),display_order:Number(value("#catalog-order")),is_active:value("#catalog-active")==="true",description:value("#catalog-description").trim(),eligible_package_codes:$$('input[name="eligible"]:checked',$("#modal")).map(x=>x.value)})});closeModal();toast("Add-on saved");renderPackages()},"Choose the exact packages that are allowed to use this extra.")}
function catalogCode(text){const code=String(text||"").toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"_").replace(/^_+|_+$/g,"").slice(0,20).replace(/_+$/g,"");return code.length>=2?code:`item_${code||"new"}`.slice(0,20)}
function wireAutomaticCatalogCode(){const name=$("#catalog-name"),code=$("#catalog-code");if(!name||!code)return;let manuallyChanged=false;code.oninput=()=>{manuallyChanged=true};name.oninput=()=>{if(!manuallyChanged)code.value=catalogCode(name.value)}}
function newPackage(packages){showModal("Add wedding package",`<label class="full">Package name<input id="catalog-name" required></label><label>Internal code<input id="catalog-code" minlength="2" maxlength="20" pattern="[a-z0-9_-]{2,20}" placeholder="Created automatically" title="Use 2 to 20 lowercase letters, numbers, underscores or hyphens" required><small class="field-help">Created automatically from the package name.</small></label><label>Display position<input id="catalog-order" type="number" min="0" value="${packages.length+1}" required></label><label>Price<input id="catalog-price" type="number" min="0" step="0.01" required></label><label>Booking fee / deposit<input id="catalog-deposit" type="number" min="0" step="0.01" required></label><label class="full">Full package wording<textarea id="catalog-description" rows="12" required></textarea></label>`,async()=>{await api("/api/catalog/packages?brand=wbm",{method:"POST",body:JSON.stringify({code:value("#catalog-code").trim().toLowerCase(),name:value("#catalog-name").trim(),price:Number(value("#catalog-price")),deposit_amount:Number(value("#catalog-deposit")),display_order:Number(value("#catalog-order")),description:value("#catalog-description").trim(),is_active:true})});closeModal();toast("Package added");renderPackages()});wireAutomaticCatalogCode()}
function newAddon(packages,addons){const checks=packages.map(p=>`<label class="check-option"><input type="checkbox" name="eligible" value="${p.code}"><span>${esc(p.name)}</span></label>`).join("");showModal("Add optional extra",`<label class="full">Add-on name<input id="catalog-name" required></label><label>Internal code<input id="catalog-code" minlength="2" maxlength="20" pattern="[a-z0-9_-]{2,20}" placeholder="Created automatically" title="Use 2 to 20 lowercase letters, numbers, underscores or hyphens" required><small class="field-help">Created automatically from the add-on name.</small></label><label>Display position<input id="catalog-order" type="number" min="0" value="${addons.length+1}" required></label><label>Price<input id="catalog-price" type="number" min="0" step="0.01" required></label><label class="full">Description<textarea id="catalog-description" rows="5" required></textarea></label><div class="full"><div class="section-label">AVAILABLE WITH</div><div class="check-grid">${checks}</div></div>`,async()=>{await api("/api/catalog/addons?brand=wbm",{method:"POST",body:JSON.stringify({code:value("#catalog-code").trim().toLowerCase(),name:value("#catalog-name").trim(),price:Number(value("#catalog-price")),display_order:Number(value("#catalog-order")),description:value("#catalog-description").trim(),eligible_package_codes:$$('input[name="eligible"]:checked',$("#modal")).map(x=>x.value),is_active:true})});closeModal();toast("Add-on added");renderPackages()});wireAutomaticCatalogCode()}

async function renderCommunicationsV2(){
  const view=state.view;$("#content").innerHTML=`<div class="panel loading">Loading templates…</div>`;
  try{
    const qs=state.brand==="all"?"":`?brand=${state.brand}`,d=await api(`/api/communications/templates${qs}`);if(state.view!==view)return;
    const wbm=d.smtp_by_brand.wbm,ivory=d.smtp_by_brand.ivory;
    $("#content").innerHTML=`<section class="comm-status email-status"><div class="${wbm.configured?"ready":"warning-box"}"><strong>Weddings By Mark email ${wbm.configured?"ready":"needs password"}</strong><span>${esc(wbm.username||"mark@perfectweddingsbymark.uk")}</span></div><div class="${ivory.configured?"ready":"warning-box"}"><strong>Ivory Digital email ${ivory.configured?"ready":"needs password"}</strong><span>${esc(ivory.username||"admin@ivorydigital.uk")}</span></div><div class="${d.reminders_enabled?"ready":"warning-box"}"><strong>Automatic reminders ${d.reminders_enabled?"enabled":"paused"}</strong><span>${d.reminders_enabled?"The system scans automatically.":"Enable after both email accounts have been tested."}</span></div><button id="run-reminders" class="secondary" ${d.smtp_configured?"":"disabled"}>Run reminder check</button></section><div class="comm-grid"><section class="panel"><div class="panel-title"><div><h2>Email templates</h2><p>Edit, preview and send a safe test before using a template</p></div></div><div class="template-list">${d.templates.map(t=>`<article class="template-row-v8"><i class="brand-badge ${t.brand}">${t.brand==="wbm"?"WBM":"ID"}</i><span><strong>${esc(t.display_name)}</strong><small>${esc(t.subject)}</small></span><div class="template-actions"><button class="mini" data-preview-template="${t.id}">Preview</button><button class="mini" data-edit-template="${t.id}">Edit</button></div></article>`).join("")}</div></section><section class="panel"><div class="panel-title"><div><h2>Agreement templates</h2><p>The exact accepted wording is permanently snapshotted</p></div></div><div class="template-list">${d.contracts.filter(c=>state.brand==="all"||c.brand===state.brand).map(c=>`<button class="template-row" data-contract="${c.id}"><i class="brand-badge ${c.brand}">${c.brand==="wbm"?"WBM":"ID"}</i><span><strong>${esc(c.title)}</strong><small>${esc(c.version)}</small></span><b>Edit</b></button>`).join("")}</div></section></div>`;
    $$('[data-edit-template]').forEach(b=>b.onclick=()=>editEmailTemplate(d.templates.find(x=>x.id===b.dataset.editTemplate)));
    $$('[data-preview-template]').forEach(b=>b.onclick=()=>previewEmailTemplate(d.templates.find(x=>x.id===b.dataset.previewTemplate)));
    $$('[data-contract]').forEach(b=>b.onclick=()=>editContractTemplate(d.contracts.find(x=>x.id===b.dataset.contract)));
    $("#run-reminders").onclick=async()=>{try{const result=await api("/api/communications/reminders/run",{method:"POST"});toast(`Reminder check: ${result.sent} sent, ${result.failed} failed`)}catch(e){toast(e.message,"error")}};
  }catch(e){showError(e)}
}

async function renderCommunications(){return renderCommunicationsV2()}
function editEmailTemplate(t){showModal(`Edit ${t.display_name}`,`<label class="full">Template name<input id="template-name" value="${attr(t.display_name)}" required></label><label class="full">Subject<input id="template-subject" value="${attr(t.subject)}" required></label><label class="full">Email body<textarea id="template-body" rows="14" required>${esc(t.body)}</textarea></label>`,async()=>{await api(`/api/communications/templates/${t.id}`,{method:"PATCH",body:JSON.stringify({display_name:value("#template-name").trim(),subject:value("#template-subject").trim(),body:value("#template-body").trim()})});closeModal();toast("Email template saved");renderCommunications()},"Changes apply to future emails only.")}
async function previewEmailTemplate(t){try{const p=await api(`/api/communications/templates/${t.id}/preview`),content=$("#modal-content");content.innerHTML=`<div class="modal-head"><div><small>${t.brand==="wbm"?"WEDDINGS BY MARK":"IVORY DIGITAL"}</small><h2>${esc(t.display_name)} preview</h2><p>This is how the branded email will look using example booking details.</p></div><button type="button" id="close-modal">×</button></div><div class="form-grid" style="display:block"><div class="email-preview-shell"><div class="email-preview-toolbar"><span><strong>${esc(p.subject)}</strong><small>Nothing is sent until you press Send test.</small></span><div class="email-preview-send"><input id="test-recipient" type="email" value="${attr(p.test_recipient)}" aria-label="Test recipient"><button id="send-test-email" class="primary">Send test</button></div></div><iframe id="email-preview-frame" class="email-preview-frame" title="Email preview"></iframe></div></div>`;$("#modal").classList.remove("hidden");$("#modal-overlay").classList.remove("hidden");$("#close-modal").onclick=closeModal;$("#email-preview-frame").srcdoc=p.html;$("#send-test-email").onclick=async()=>{const button=$("#send-test-email");button.disabled=true;button.textContent="Sending…";try{const result=await api(`/api/communications/templates/${t.id}/test`,{method:"POST",body:JSON.stringify({recipient:value("#test-recipient")})});toast(`Test email sent to ${result.recipient}`);button.textContent="Sent ✓"}catch(e){button.disabled=false;button.textContent="Send test";toast(e.message,"error")}}}catch(e){toast(e.message,"error")}}
function editContractTemplate(c){showModal(`Edit ${c.title}`,`<label>Agreement title<input id="contract-title" value="${attr(c.title)}" required></label><label>Version<input id="contract-version" value="${attr(c.version)}" required></label><label class="full">Complete agreement wording<textarea id="contract-body" rows="18" required>${esc(c.body)}</textarea></label>`,async()=>{await api(`/api/communications/contracts/${c.id}`,{method:"PATCH",body:JSON.stringify({title:value("#contract-title").trim(),version:value("#contract-version").trim(),body:value("#contract-body").trim()})});closeModal();toast("Agreement template saved");renderCommunications()},"Already accepted agreements keep their original wording.")}

function renderSettings(){const rows=state.businesses.filter(b=>state.brand==="all"||b.brand===state.brand);$("#content").innerHTML=`<div class="settings-grid">${rows.map(b=>{const bank=b.bank_details||{};return `<form class="panel business-form" data-business="${b.brand}"><div class="business-head ${b.brand}"><span>${b.brand==="wbm"?"WBM":"ID"}</span><div><h2>${esc(b.display_name)}</h2><p>Invoice prefix ${esc(b.invoice_prefix)}</p></div></div><div class="settings-fields"><label>Trading name<input name="display_name" value="${attr(b.display_name)}" required></label><label>Legal name<input name="legal_name" value="${attr(b.legal_name)}" required></label><label>Email<input name="email" type="email" value="${attr(b.email||"")}"></label><label>Phone<input name="phone" value="${attr(b.phone||"")}"></label><label class="full">Website<input name="website" value="${attr(b.website||"")}"></label><label class="full">Address<textarea name="address" rows="2">${esc(b.address||"")}</textarea></label><div class="section-label full">BANK TRANSFER DETAILS</div><label>Account name<input name="account_name" value="${attr(bank.account_name||"")}"></label><label>Sort code<input name="sort_code" value="${attr(bank.sort_code||"")}"></label><label class="full">Account number<input name="account_number" value="${attr(bank.account_number||"")}"></label></div><footer><button class="primary" type="submit">Save ${esc(b.display_name)}</button></footer></form>`}).join("")}</div>`;$$('.business-form').forEach(f=>f.onsubmit=saveBusiness)}
async function saveBusiness(e){e.preventDefault();const f=e.currentTarget,fd=new FormData(f);const payload={display_name:fd.get("display_name"),legal_name:fd.get("legal_name"),email:nullable(fd.get("email")),phone:nullable(fd.get("phone")),website:nullable(fd.get("website")),address:nullable(fd.get("address")),bank_details:{account_name:nullable(fd.get("account_name")),sort_code:nullable(fd.get("sort_code")),account_number:nullable(fd.get("account_number"))}};try{state.businesses=await api(`/api/businesses/${f.dataset.business}`,{method:"PATCH",body:JSON.stringify(payload)});toast("Business details saved");renderSettings()}catch(err){toast(err.message,"error")}}

function showModal(title,fields,onSubmit,subtitle="Make the changes below, then save."){const content=$("#modal-content");content.innerHTML=`<div class="modal-head"><div><small>MARK'S BUSINESS STUDIO</small><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button type="button" id="close-modal">×</button></div><form id="dynamic-form"><div class="form-grid">${fields}</div><p id="form-error" class="error"></p><footer><button class="secondary" id="cancel-modal" type="button">Cancel</button><button class="primary" type="submit">Save</button></footer></form>`;$("#modal").classList.remove("hidden");$("#modal-overlay").classList.remove("hidden");$("#close-modal").onclick=$("#cancel-modal").onclick=closeModal;$("#dynamic-form").onsubmit=async e=>{e.preventDefault();$("#form-error").textContent="";try{await onSubmit(e)}catch(err){$("#form-error").textContent=err.message}};setTimeout(()=>$("#dynamic-form input, #dynamic-form select, #dynamic-form textarea")?.focus(),40)}
