function recordFields(r={}){const c=r.client||{};const venue=r.brand==="ivory"?`<label>Project<input id="form-detail" value="${attr(r.venue_or_project||"")}"></label>`:`<label class="full venue-admin-field">Wedding venue<input id="form-detail" type="hidden" value="${attr(r.venue_or_project||"")}"><input id="form-venue-address" type="hidden" value="${attr(r.venue_address||"")}"><input id="form-venue-place-id" type="hidden" value="${attr(r.venue_place_id||"")}"><input id="form-venue-lat" type="hidden" value="${attr(r.venue_lat??"")}"><input id="form-venue-lng" type="hidden" value="${attr(r.venue_lng??"")}"><div id="form-venue-picker" class="venue-picker"></div><input id="form-venue-manual" placeholder="Enter the venue manually" hidden><div id="form-venue-summary" class="venue-summary"><span>No venue selected yet</span></div><button id="form-venue-manual-toggle" class="venue-manual-toggle" type="button">Can't find it? Enter the venue manually</button></label>`;return `<label class="full">Business<select id="form-brand" ${r.id?"disabled":""}><option value="wbm" ${r.brand==="wbm"?"selected":""}>Weddings By Mark</option><option value="ivory" ${r.brand==="ivory"?"selected":""}>Ivory Digital</option></select></label><label class="full">Record title<input id="form-title" value="${attr(r.title||"")}" required placeholder="Sophie & James"></label><label>First name / contact<input id="form-first" value="${attr(c.first_name||"")}" required></label><label>Last name<input id="form-last" value="${attr(c.last_name||"")}"></label><label>Partner name<input id="form-partner" value="${attr(c.partner_name||"")}"></label><label>Company name<input id="form-company" value="${attr(c.company_name||"")}"></label><label>Email address<input id="form-email" type="email" value="${attr(c.email||"")}" required></label><label>Phone number<input id="form-phone" value="${attr(c.phone||"")}"></label><label class="full">Address<textarea id="form-address" rows="2">${esc(c.address||"")}</textarea></label><label>Status<select id="form-status">${statuses.map(s=>`<option value="${s}" ${(r.status||"enquiry")===s?"selected":""}>${statusText(s)}</option>`).join("")}</select></label><label>Wedding / target date<input id="form-date" type="date" value="${attr(r.event_date||"")}"></label>${venue}<label>Package / service<input id="form-package" value="${attr(r.package_name||"")}"></label><label>Quoted total<input id="form-total" type="number" min="0" step="0.01" value="${Number(r.quoted_total||0)}"></label><label>Deposit amount<input id="form-deposit" type="number" min="0" step="0.01" value="${Number(r.deposit_amount||0)}"></label><label>Deposit paid date<input id="form-deposit-date" type="date" value="${attr(r.deposit_paid_date||"")}"></label><label>Balance due date<input id="form-balance-date" type="date" value="${attr(r.balance_due_date||"")}"></label><label class="full">Main notes<textarea id="form-notes" rows="3">${esc(r.notes||"")}</textarea></label>`}
function recordPayload(existing=false){const brand=existing?state.current.brand:value("#form-brand");return {title:value("#form-title").trim(),status:value("#form-status"),event_date:nullable(value("#form-date")),venue_or_project:nullable(value("#form-detail")),venue_address:nullable(value("#form-venue-address")),venue_place_id:nullable(value("#form-venue-place-id")),venue_lat:nullable(value("#form-venue-lat"))===null?null:Number(value("#form-venue-lat")),venue_lng:nullable(value("#form-venue-lng"))===null?null:Number(value("#form-venue-lng")),package_name:nullable(value("#form-package")),quoted_total:Number(value("#form-total")||0),deposit_amount:Number(value("#form-deposit")||0),deposit_paid_date:nullable(value("#form-deposit-date")),balance_due_date:nullable(value("#form-balance-date")),notes:nullable(value("#form-notes")),client:{first_name:value("#form-first").trim(),last_name:value("#form-last").trim(),partner_name:nullable(value("#form-partner")),company_name:nullable(value("#form-company")),email:value("#form-email").trim(),phone:nullable(value("#form-phone")),address:nullable(value("#form-address"))},...(existing?{}:{brand,kind:brand==="wbm"?"wedding":"digital"})}}
function openRecordModal(r=null){const digital=!r&&(state.view==="projects"||state.brand==="ivory");const base=r||{brand:digital?"ivory":"wbm",status:"enquiry",client:{}};showModal(r?"Edit full record":digital?"Add a digital project":"Add a new booking",recordFields(base),async()=>{const payload=recordPayload(!!r);if(r)await api(`/api/bookings/${r.id}`,{method:"PATCH",body:JSON.stringify(payload)});else await api("/api/bookings",{method:"POST",body:JSON.stringify(payload)});closeModal();await refresh();toast(r?"Record updated":payload.kind==="wedding"?"Wedding booking created":"Digital project created");if(r)openDrawer(r.id);else navigate(payload.kind==="wedding"?"weddings":"projects")},r?"Update contact, booking, venue, status and payment dates.":"Start with as much detail as you have. Everything stays editable.");if(base.brand==="wbm")setTimeout(()=>window.WBMVenues?.attach({host:"#form-venue-picker",manual:"#form-venue-manual",manualToggle:"#form-venue-manual-toggle",summary:"#form-venue-summary",name:"#form-detail",address:"#form-venue-address",placeId:"#form-venue-place-id",lat:"#form-venue-lat",lng:"#form-venue-lng",placeholder:"Start typing the wedding venue"}),0)}

function normaliseRecordTab(tab){return ({"Client portal":"Journey","Workflow":"Journey","Finance":"Payments","Documents":"Files","Notes & activity":"Notes"})[tab]||tab||"Overview"}
function recordInvoiceTotals(r){const active=(r.invoices||[]).filter(i=>i.status!=="void"),paid=(r.invoices||[]).reduce((sum,i)=>sum+Number(i.paid||0),0),outstanding=active.reduce((sum,i)=>sum+Number(i.balance||0),0);return {paid,outstanding}}
function recordJourneyFacts(r,portal){const submissions=portal?.submissions||[],emails=portal?.emails||[],totals=recordInvoiceTotals(r);return {quote:portal?.quote||null,quoteSent:emails.some(e=>e.template_key==="quote"&&e.status==="sent"),bookingForm:submissions.find(x=>x.form_type==="booking_form"),finalForm:submissions.find(x=>x.form_type==="final_questionnaire"),contract:portal?.contract||null,finalUnlocked:Boolean(portal?.final_details_unlocked),paid:totals.paid,outstanding:totals.outstanding,hasPayment:totals.paid>0||Boolean(r.deposit_paid_date)}}
function recordJourneyStrip(r,portal){if(r.kind!=="wedding")return "";const f=recordJourneyFacts(r,portal),today=new Date().toISOString().slice(0,10),pastWedding=Boolean(r.event_date&&r.event_date<today),steps=[{label:"Enquiry",done:true},{label:"Quote",done:Boolean(f.quote),current:!f.quote},{label:"Payment",done:f.hasPayment,current:Boolean(f.quote&&!f.hasPayment)},{label:"Forms",done:Boolean(f.bookingForm&&f.contract),current:Boolean(f.hasPayment&&!(f.bookingForm&&f.contract))},{label:"Wedding",done:r.status==="completed"||pastWedding,current:Boolean(f.hasPayment&&f.bookingForm&&f.contract&&r.status!=="completed"&&!pastWedding)}];return `<section class="record-journey-strip">${steps.map((step,index)=>`<div class="${step.done?"done":step.current?"current":""}"><i>${step.done?"✓":index+1}</i><span>${step.label}</span></div>`).join("")}</section>`}
function recordNextAction(r,portal){const f=recordJourneyFacts(r,portal);if(r.status==="cancelled")return {title:"This record is cancelled",detail:"Reopen it before taking any further booking action.",tab:"Overview",quiet:true};if(r.legacy_source==="studio_ninja"){if(f.outstanding>0)return {title:`Review the outstanding balance · ${money(f.outstanding)}`,detail:"This imported wedding stays manual-only. Record bank transfers yourself when they arrive.",tab:"Payments",label:"Open payments"};if(f.finalUnlocked&&!f.finalForm)return {title:"Final wedding details are ready",detail:"Studio Ninja communications remain paused; review this manually when you are ready.",tab:"Journey",label:"Open journey"};return {title:"Imported booking is safely on track",detail:"It remains visible here while Studio Ninja handles the existing client messages.",tab:"Overview",label:"Review booking",quiet:true}}if(r.kind!=="wedding"){if(f.outstanding>0)return {title:`Payment outstanding · ${money(f.outstanding)}`,detail:"Open the project payments and record any bank transfer received.",tab:"Payments",label:"Open payments"};return {title:"Review this digital project",detail:"Contact details, files, notes and payments are grouped below.",tab:"Overview",label:"Open overview",quiet:true}}if(!f.quote){if(f.quoteSent)return {title:"Waiting for the couple to choose a package",detail:"The quote has been sent. Their package choice will update this booking automatically.",tab:"Journey",label:"View quote journey",quiet:true};return {title:"Send the package quote",detail:"This is the next step after receiving and checking their enquiry.",tab:"Journey",label:"Open quote"}}if(!f.hasPayment)return {title:"Record their first payment",detail:"Any first bank transfer secures the wedding, including a part-payment.",tab:"Payments",label:"Open payments"};if(!f.bookingForm)return {title:"Waiting for the Wedding Booking Form",detail:"Open the journey to view the couple's progress or send their booking link again.",tab:"Journey",label:"Open journey"};if(!f.contract)return {title:"Waiting for the wedding contract",detail:"Open the journey to check the agreement or send a polite reminder.",tab:"Journey",label:"Open journey"};if(f.finalUnlocked&&!f.finalForm)return {title:"Final wedding details are now due",detail:"The final questionnaire is open for the couple to complete.",tab:"Journey",label:"Open final details"};if(f.outstanding>0&&r.balance_due_date)return {title:`Balance remaining · ${money(f.outstanding)}`,detail:`The final balance is due ${fmtDate(r.balance_due_date)}.`,tab:"Payments",label:"Open payments",quiet:true};const openTasks=(r.tasks||[]).filter(t=>!t.completed);if(openTasks.length)return {title:`${openTasks.length} thing${openTasks.length===1?"":"s"} still to do`,detail:"Open the journey to see the short task list for this booking.",tab:"Journey",label:"View tasks",quiet:true};return {title:"Everything is on track",detail:"There is nothing you need to do for this wedding at the moment.",tab:"Overview",label:"Review booking",quiet:true}}
function recordSectionNavigation(selected,mobile=false){const sections=[{tab:"Overview",icon:"♡",label:mobile?"Client & wedding":"Overview",help:"Contact, venue and booking details"},{tab:"Journey",icon:"✓",label:mobile?"Quote & workflow":"Journey",help:"Quote, forms, agreement, emails and tasks"},{tab:"Payments",icon:"£",label:mobile?"Invoices & payments":"Payments",help:"Invoices, balances and bank transfers"},{tab:"Files",icon:"▤",label:"Files",help:"Contracts, questionnaires and documents"},{tab:"Notes",icon:"✎",label:"Notes",help:"Private notes and booking history"}];if(!mobile)return `<div class="tabs guided-tabs">${sections.map(x=>`<button class="${x.tab===selected?"active":""}" data-tab="${x.tab}">${x.label}</button>`).join("")}</div><div id="drawer-body" class="drawer-body"></div>`;return `<div class="guided-accordions">${sections.map(x=>`<section class="guided-accordion ${x.tab===selected?"open":""}"><button data-tab="${x.tab}" aria-expanded="${x.tab===selected}"><i>${x.icon}</i><span><strong>${x.label}</strong><small>${x.help}</small></span><b>⌄</b></button><div class="drawer-body ${x.tab===selected?"":"hidden"}" data-section-body="${x.tab}"></div></section>`).join("")}</div>`}
function selectRecordTab(r,tab,scroll=false){const selected=normaliseRecordTab(tab),drawer=$("#drawer");state.currentTab=selected;$$('[data-tab]',drawer).forEach(button=>{const active=button.dataset.tab===selected;button.classList.toggle("active",active);button.setAttribute("aria-expanded",String(active));button.closest(".guided-accordion")?.classList.toggle("open",active)});const mobileBody=$(`[data-section-body="${selected}"]`,drawer);if(mobileBody){$$('[data-section-body]',drawer).forEach(body=>body.classList.toggle("hidden",body!==mobileBody));renderTab(r,selected,mobileBody);if(scroll)setTimeout(()=>mobileBody.closest(".guided-accordion")?.scrollIntoView({behavior:"smooth",block:"start"}),30)}else renderTab(r,selected)}
async function openDrawer(id,tab="Overview"){
  try{
    const [r,portal]=await Promise.all([api(`/api/bookings/${id}`),api(`/api/bookings/${id}/portal`).catch(()=>null)]),selected=normaliseRecordTab(tab),next=recordNextAction(r,portal);
    state.current=r;state.currentPortal=portal;state.currentTab=selected;
    const drawer=$("#drawer");
    drawer.innerHTML=`<div class="drawer-head guided-head ${r.brand}"><div class="drawer-person"><span>${esc(initials(r))}</span><div><small>${r.legacy_source==="studio_ninja"?"IMPORTED · MANUAL COMMUNICATION":r.kind==="wedding"?"WEDDING BOOKING":"IVORY DIGITAL PROJECT"}</small><h2>${esc(r.title)}</h2><p>${esc(r.venue_or_project||"Details not set")} · ${esc(fmtDate(r.event_date))}</p><div class="record-head-links"><a href="mailto:${attr(r.client.email)}">Email</a>${r.client.phone?`<a href="tel:${attr(r.client.phone)}">Call</a>`:""}${venueDirections(r)?`<a href="${attr(venueDirections(r))}" target="_blank" rel="noopener">Directions</a>`:""}</div></div></div><div class="record-head-status"><span class="status ${statusClass(r.status)}">${esc(statusText(r.status))}</span><button id="close-drawer" aria-label="Back to bookings"><span>←</span> Back to bookings</button></div></div>${recordJourneyStrip(r,portal)}<section class="record-next-action ${next.quiet?"quiet":""}"><i>→</i><div><small>YOUR NEXT STEP</small><strong>${esc(next.title)}</strong><span>${esc(next.detail)}</span></div>${next.label?`<button id="next-record-action" class="${next.quiet?"secondary":"primary"}">${esc(next.label)}</button>`:""}</section>${recordSectionNavigation(selected,true)}<footer><button class="secondary ${r.archived?"":"danger-button"}" id="archive-record">${r.archived?"Restore record":"Archive record"}</button><button class="primary" id="edit-record">Edit booking details</button></footer>`;
    drawer.classList.remove("hidden");$("#drawer-overlay").classList.remove("hidden");$("#close-drawer").onclick=closeDrawer;$("#edit-record").onclick=()=>openRecordModal(r);$("#archive-record").onclick=()=>toggleArchive(r);if($("#next-record-action"))$("#next-record-action").onclick=()=>selectRecordTab(r,next.tab,true);$$('[data-tab]',drawer).forEach(b=>b.onclick=()=>selectRecordTab(r,b.dataset.tab,true));selectRecordTab(r,selected)
  }catch(e){toast(e.message,"error")}
}
function closeDrawer(){$("#drawer").classList.add("hidden");$("#drawer-overlay").classList.add("hidden");state.current=null;state.currentPortal=null;state.currentTab=null}
async function renderTab(r,tab,target=null){const body=target||$("#drawer-body"),selected=normaliseRecordTab(tab);if(!body)return;if(selected==="Overview")renderOverview(r,body);else if(selected==="Journey"){await renderQuotePortal(r,body);appendJourneyTasks(r,body)}else if(selected==="Payments")renderFinance(r,body);else if(selected==="Files")renderRecordDocuments(r,body);else renderNotes(r,body)}
function renderOverview(r,body){
  const directions=venueDirections(r);
  const legacy=r.legacy_source==="studio_ninja"?`<section class="legacy-banner"><strong>Imported safely from Studio Ninja · manual communication only</strong><span>Original reference: ${esc(r.legacy_id||"Not supplied")} · Batch ${esc(r.legacy_import_batch||"Not supplied")}</span><em>Fully visible on your dashboard, upcoming dates and calendar. Automatic emails and reminders stay permanently paused.</em></section>`:"";
  body.innerHTML=`${legacy}<section class="workspace-shortcuts"><button data-workspace-tab="Journey"><i>✉</i><span><strong>Quote & client journey</strong><small>Emails, forms and agreement</small></span></button><button data-workspace-tab="Payments"><i>£</i><span><strong>Payments</strong><small>Invoices and bank transfers</small></span></button><button data-workspace-tab="Files"><i>▤</i><span><strong>Files</strong><small>Contracts and documents</small></span></button><button data-workspace-tab="Notes"><i>＋</i><span><strong>Notes</strong><small>Private history and reminders</small></span></button></section><section class="summary"><div><small>STATUS</small><strong class="status ${statusClass(r.status)}">${esc(statusText(r.status))}</strong></div><div><small>PACKAGE / SERVICE</small><strong>${esc(r.package_name||"Not selected")}</strong></div><div><small>VALUE</small><strong>${money(r.quoted_total)}</strong></div></section><section class="detail-grid"><article class="detail"><h3>Contact</h3><dl><dt>Name</dt><dd>${esc([r.client.first_name,r.client.last_name].filter(Boolean).join(" "))}</dd>${r.client.partner_name?`<dt>Partner</dt><dd>${esc(r.client.partner_name)}</dd>`:""}${r.client.company_name?`<dt>Company</dt><dd>${esc(r.client.company_name)}</dd>`:""}<dt>Email</dt><dd><a href="mailto:${attr(r.client.email)}">${esc(r.client.email)}</a></dd><dt>Phone</dt><dd>${esc(r.client.phone||"Not set")}</dd><dt>Address</dt><dd>${esc(r.client.address||"Not set")}</dd></dl></article><article class="detail"><h3>Wedding / project</h3><dl><dt>Date</dt><dd>${esc(fmtDate(r.event_date))}</dd><dt>Venue / project</dt><dd>${directions?`<a class="directions-link" href="${attr(directions)}" target="_blank" rel="noopener">${esc(r.venue_or_project||r.venue_address)} ↗</a>${r.venue_address&&r.venue_address!==r.venue_or_project?`<small>${esc(r.venue_address)}</small>`:""}`:esc(r.venue_or_project||"Not set")}</dd><dt>First payment</dt><dd>${r.deposit_paid_date?`Received ${esc(fmtDate(r.deposit_paid_date))}`:"Not recorded"}</dd><dt>Balance due</dt><dd>${esc(fmtDate(r.balance_due_date))}</dd></dl></article></section><article class="detail"><h3>Main notes</h3><p class="preline">${esc(r.notes||"No main notes added yet.")}</p></article>`;
  $$('[data-workspace-tab]',body).forEach(button=>button.onclick=()=>selectRecordTab(r,button.dataset.workspaceTab));
}
function createManualPortalLink(r,body){
  showModal("Create one manual portal link",`<label class="full">Reason<input id="manual-link-reason" value="Manual client access requested by Mark" required></label><label class="full">Type CREATE MANUAL LINK<input id="manual-link-confirm" autocomplete="off" required></label>`,async()=>{const x=await api(`/api/bookings/${r.id}/portal`,{method:"POST",body:JSON.stringify({expires_days:365,manual_reason:value("#manual-link-reason").trim(),manual_confirmation:value("#manual-link-confirm").trim()})});state.portalLinks[r.id]=x.url;closeModal();toast("Manual portal link created; automatic messages remain off");renderQuotePortal(r,body)},"This creates a link for you to preview or copy. It sends no email and does not enable reminders.")
}
function sendOneManualPortalEmail(r,body,url){
  const templateKey=value("#portal-email-template");
  const templateLabel=$("#portal-email-template")?.selectedOptions?.[0]?.textContent||statusText(templateKey);
  showModal("Send one manual email",`<div class="manual-email-warning full"><strong>${esc(templateLabel)}</strong><span>Recipient: ${esc(r.client.email)}</span><small>Only this one email will be sent. Automatic reminders remain permanently paused.</small></div><label class="full">Reason<input id="manual-email-reason" value="One-off email sent manually by Mark" required></label><label class="full">Type SEND ONE MANUAL EMAIL<input id="manual-email-confirm" autocomplete="off" required></label>`,async()=>{await api(`/api/bookings/${r.id}/emails/send`,{method:"POST",body:JSON.stringify({template_key:templateKey,portal_url:url,manual_reason:value("#manual-email-reason").trim(),manual_confirmation:value("#manual-email-confirm").trim()})});closeModal();toast("One manual email sent; automatic messages remain off");renderQuotePortal(r,body)},"Check the recipient and selected template carefully before confirming.")
}
async function renderQuotePortal(r,body){
  if(r.kind!=="wedding")return renderClientPortal(r,body);
  body.innerHTML=`<div class="loading">Loading quote and client portal…</div>`;
  try{
    const d=await api(`/api/bookings/${r.id}/portal`),url=state.portalLinks[r.id]||"";
    const bookingForm=d.submissions.find(x=>x.form_type==="booking_form"),finalForm=d.submissions.find(x=>x.form_type==="final_questionnaire");
    const isLegacy=r.legacy_source==="studio_ninja";
    const safety=isLegacy?`<section class="automation-card paused manual-only-card"><span><strong>Studio Ninja · manual communication only</strong><small>This confirmed wedding stays visible throughout the dashboard, upcoming dates and calendar. Automatic emails, payment confirmations and reminders are permanently off.</small></span><em>MANUAL ONLY</em></section>`:"";
    const finalControl=`<section class="automation-card"><span><strong>Final wedding details</strong><small>${d.final_details_unlocked?"Available to the couple now.":"Locked until 30 days before the wedding."}</small></span>${d.final_details_unlocked?(r.workflow_state?.final_details_manual_unlock?`<button id="schedule-final-details" class="secondary">Return to 30-day schedule</button>`:""):`<button id="unlock-final-details" class="secondary">Open early</button>`}</section>`;
    body.innerHTML=`${safety}${finalControl}<section class="quote-send-card ${d.quote?"accepted":""}"><div><small>INITIAL CUSTOMER JOURNEY</small><h3>${d.quote?"Package quote accepted":"Create and send their package quote"}</h3><p>${d.quote?`${esc(d.quote.line_items[0]?.name||"Package")} · ${money(d.quote.total)} · Invoice ${esc(d.quote.invoice_number||"created")}`:`This creates a secure link, emails ${esc(r.client.email)} and opens the couple directly on the package choices.`}</p></div>${d.quote?`<span class="quote-done">✓ Accepted</span>`:`<button id="send-quote" class="primary">Create & send quote</button>`}</section>
      ${url?`<div class="portal-link"><input id="portal-url" readonly value="${attr(url)}"><a class="secondary portal-preview" href="${attr(url)}" target="_blank" rel="noopener">Preview</a><button id="copy-link" class="secondary">Copy</button></div>`:`<div class="quote-help">${isLegacy?"Create a manual portal link only when you are ready. Nothing will be emailed automatically.":"Press <strong>Create & send quote</strong>. Their wedding booking link will appear here automatically."}</div>`}
      <div class="section-actions compact"><div><h3>${isLegacy?"Manual client access":"Other client messages"}</h3><p>${isLegacy?"Create or send only when you deliberately choose to":"Booking form, final details and agreement reminders"}</p></div><button id="generate-link" class="secondary">${isLegacy?"Create manual portal link":"Generate general portal link"}</button></div>
      ${url?`<div class="portal-email"><select id="portal-email-template"><option value="booking_link">Booking link</option><option value="final_questionnaire">Final questionnaire</option><option value="contract_reminder">Agreement reminder</option></select><button id="send-portal-email" class="secondary">${isLegacy?"Review & send one manual email":"Send selected email"}</button></div>`:""}
      <section class="portal-progress"><article><i class="${d.quote?"complete":""}">${d.quote?"✓":"1"}</i><span><strong>Package quote</strong><small>${d.quote?`Accepted ${fmtDateTime(d.quote.accepted_at)}`:"Waiting for package selection"}</small></span></article><article><i class="${bookingForm?"complete":""}">${bookingForm?"✓":"2"}</i><span><strong>Wedding Booking Form</strong><small>${bookingForm?`Submitted ${fmtDateTime(bookingForm.submitted_at)}`:"Waiting"}</small></span></article><article><i class="${finalForm?"complete":""}">${finalForm?"✓":"3"}</i><span><strong>Final questionnaire</strong><small>${finalForm?`Submitted ${fmtDateTime(finalForm.submitted_at)}`:"Waiting"}</small></span></article><article><i class="${d.contract?"complete":""}">${d.contract?"✓":"4"}</i><span><strong>Agreement</strong><small>${d.contract?`Accepted by ${esc(d.contract.accepted_name)} · ${fmtDateTime(d.contract.accepted_at)}`:"Waiting"}</small></span></article></section>
      <h3 class="section-title">Email history</h3><div class="activity-list">${d.emails.map(e=>`<div><i></i><span><strong>${esc(statusText(e.template_key))} · ${esc(e.status)}</strong><small>${esc(e.subject)} · ${fmtDateTime(e.sent_at)}</small></span></div>`).join("")||`<p class="muted" style="padding:14px">No emails sent from this record yet.</p>`}</div>`;
    if($("#unlock-final-details"))$("#unlock-final-details").onclick=()=>showModal("Open final wedding details early",`<label class="full">Reason<input id="final-reason" value="Opened early by Mark" required></label>`,async()=>{await api(`/api/bookings/${r.id}/final-details`,{method:"POST",body:JSON.stringify({unlocked:true,reason:value("#final-reason")})});closeModal();toast("Final details opened");openDrawer(r.id,"Client portal")});
    if($("#schedule-final-details"))$("#schedule-final-details").onclick=async()=>{await api(`/api/bookings/${r.id}/final-details`,{method:"POST",body:JSON.stringify({unlocked:false,reason:"Returned to the automatic 30-day schedule"})});toast("Final details returned to the 30-day schedule");openDrawer(r.id,"Client portal")};
    if($("#send-quote"))$("#send-quote").onclick=async()=>{const button=$("#send-quote");button.disabled=true;button.textContent="Creating & sending…";try{const result=await api(`/api/bookings/${r.id}/quote/send`,{method:"POST",body:JSON.stringify({expires_days:90})});state.portalLinks[r.id]=result.url;if(result.email_sent)toast("Quote email sent");else toast(`Quote link created, but email was not sent: ${result.email_error}`,"error");renderQuotePortal(r,body)}catch(e){button.disabled=false;button.textContent="Create & send quote";toast(e.message,"error")}};
    $("#generate-link").onclick=isLegacy?()=>createManualPortalLink(r,body):async()=>{const x=await api(`/api/bookings/${r.id}/portal`,{method:"POST",body:JSON.stringify({expires_days:90})});state.portalLinks[r.id]=x.url;toast("General portal link generated");renderQuotePortal(r,body)};
    if(url){$("#copy-link").onclick=async()=>{await navigator.clipboard.writeText(url);toast("Wedding booking link copied")};$("#send-portal-email").onclick=isLegacy?()=>sendOneManualPortalEmail(r,body,url):async()=>{try{await api(`/api/bookings/${r.id}/emails/send`,{method:"POST",body:JSON.stringify({template_key:value("#portal-email-template"),portal_url:url})});toast("Email sent");renderQuotePortal(r,body)}catch(e){toast(e.message,"error")}}}
  }catch(e){body.innerHTML=`<div class="empty"><strong>Unable to load quote controls</strong>${esc(e.message)}</div>`}
}

async function renderClientPortal(r,body){body.innerHTML=`<div class="loading">Loading client portal…</div>`;try{const d=await api(`/api/bookings/${r.id}/portal`),url=state.portalLinks[r.id]||"";body.innerHTML=`<div class="section-actions"><div><h3>${r.kind==="wedding"?"Wedding booking area":"Secure client portal"}</h3><p>Forms, final details and electronic agreement</p></div><button id="generate-link" class="primary">Generate new link</button></div>${url?`<div class="portal-link"><input id="portal-url" readonly value="${attr(url)}"><button id="copy-link" class="secondary">Copy</button></div><div class="portal-email"><select id="portal-email-template"><option value="booking_link">Booking link</option><option value="quote">Quote email</option>${r.kind==="wedding"?`<option value="final_questionnaire">Final questionnaire</option>`:""}<option value="contract_reminder">Agreement reminder</option></select><button id="send-portal-email" class="primary">Send to ${esc(r.client.email)}</button></div>`:`<div class="empty small-empty"><strong>No active link shown</strong>Generate a new booking link. For security, links are only displayed when created.</div>`}<section class="portal-progress"><article><i class="${d.submissions.some(x=>x.form_type==="booking_form")?"complete":""}">${d.submissions.some(x=>x.form_type==="booking_form")?"✓":"1"}</i><span><strong>Booking form</strong><small>${d.submissions.some(x=>x.form_type==="booking_form")?`Submitted ${fmtDateTime(d.submissions.find(x=>x.form_type==="booking_form").submitted_at)}`:"Waiting"}</small></span></article>${r.kind==="wedding"?`<article><i class="${d.submissions.some(x=>x.form_type==="final_questionnaire")?"complete":""}">${d.submissions.some(x=>x.form_type==="final_questionnaire")?"✓":"2"}</i><span><strong>Final questionnaire</strong><small>${d.submissions.some(x=>x.form_type==="final_questionnaire")?"Submitted":"Waiting"}</small></span></article>`:""}<article><i class="${d.contract?"complete":""}">${d.contract?"✓":r.kind==="wedding"?"3":"2"}</i><span><strong>Agreement</strong><small>${d.contract?`Accepted by ${esc(d.contract.accepted_name)} · ${fmtDateTime(d.contract.accepted_at)}`:"Waiting"}</small></span></article></section><h3 class="section-title">Email history</h3><div class="activity-list">${d.emails.map(e=>`<div><i></i><span><strong>${esc(statusText(e.template_key))} · ${esc(e.status)}</strong><small>${esc(e.subject)} · ${fmtDateTime(e.sent_at)}</small></span></div>`).join("")||`<p class="muted" style="padding:14px">No emails sent from this record yet.</p>`}</div>`;$("#generate-link").onclick=async()=>{const x=await api(`/api/bookings/${r.id}/portal`,{method:"POST",body:JSON.stringify({expires_days:90})});state.portalLinks[r.id]=x.url;toast("Booking link generated");renderClientPortal(r,body)};if(url){$("#copy-link").onclick=async()=>{await navigator.clipboard.writeText(url);toast("Booking link copied")};$("#send-portal-email").onclick=async()=>{try{await api(`/api/bookings/${r.id}/emails/send`,{method:"POST",body:JSON.stringify({template_key:value("#portal-email-template"),portal_url:url})});toast("Email sent");renderClientPortal(r,body)}catch(e){toast(e.message,"error")}}}}catch(e){body.innerHTML=`<div class="empty"><strong>Unable to load client portal</strong>${esc(e.message)}</div>`}}
function renderNotes(r,body){
  const legacy=(r.legacy_timeline||[]).map(item=>`<div><i></i><span><strong>${esc(statusText(item.title||item.type||item.event||"Studio Ninja activity"))}</strong><small>${esc(item.date||item.at||item.occurred_at||"")}${item.detail?` · ${esc(item.detail)}`:""}</small></span></div>`).join("");
  body.innerHTML=`<form id="note-form" class="composer"><textarea id="note-body" rows="3" placeholder="Add a private note…" required></textarea><button class="primary" type="submit">Add note</button></form><section class="notes-list">${r.booking_notes.map(n=>`<article class="note-card" data-note="${n.id}"><div><time>${esc(fmtDateTime(n.created_at))}</time><button class="mini danger-text" data-action="delete-note">Delete</button></div><p>${esc(n.body)}</p></article>`).join("")||`<div class="empty small-empty"><strong>No notes yet</strong>Add the first private note above.</div>`}</section>${legacy?`<h3 class="section-title">Imported Studio Ninja timeline</h3><div class="activity-list legacy-timeline">${legacy}</div>`:""}<h3 class="section-title">BookingSystem2026 activity</h3><div class="activity-list">${r.activity.map(a=>`<div><i></i><span><strong>${esc(statusText(a.action))}</strong><small>${esc(fmtDateTime(a.created_at))}</small></span></div>`).join("")||"<p class='muted'>No activity recorded yet.</p>"}</div>`;
  $("#note-form").onsubmit=async e=>{e.preventDefault();await api(`/api/bookings/${r.id}/notes`,{method:"POST",body:JSON.stringify({body:value("#note-body").trim()})});toast("Note added");openDrawer(r.id,"Notes & activity")};
  $$('[data-action="delete-note"]',body).forEach(b=>b.onclick=async()=>{if(!confirm("Delete this note?"))return;await api(`/api/notes/${b.closest("[data-note]").dataset.note}`,{method:"DELETE"});toast("Note deleted");openDrawer(r.id,"Notes & activity")});
}
function renderWorkflow(r,body){const weddingGuide=r.kind==="wedding"?weddingWorkflowGuide(r.legacy_source==="studio_ninja"):"";body.innerHTML=`${weddingGuide}<div class="section-actions"><div><h3>Things for you to do</h3><p>${r.tasks.filter(t=>!t.completed).length} still open</p></div><button id="add-task" class="primary">＋ Add task</button></div><div class="task-list panel-flat">${r.tasks.map(t=>taskRow(t)).join("")||`<div class="empty small-empty"><strong>Nothing needs doing</strong>Add a private task only when you need one.</div>`}</div>`;wireTaskActions(body);$("#add-task").onclick=()=>showModal("Add workflow task",`<label class="full">Task<input id="task-title" required placeholder="Something I need to remember"></label><label class="full">Due date and time<input id="task-due" type="datetime-local"></label>`,async()=>{await api(`/api/bookings/${r.id}/tasks`,{method:"POST",body:JSON.stringify({title:value("#task-title").trim(),due_at:nullable(value("#task-due"))})});closeModal();toast("Task added");openDrawer(r.id,"Workflow")})}
function appendJourneyTasks(r,body){if(!body||body.querySelector(".journey-tasks"))return;const section=document.createElement("section");section.className="journey-tasks";section.innerHTML=`<div class="section-actions"><div><h3>Things for you to do</h3><p>${r.tasks.filter(t=>!t.completed).length} still open for this ${r.kind==="wedding"?"wedding":"project"}</p></div><button id="journey-add-task" class="secondary">＋ Add task</button></div><div class="task-list panel-flat">${r.tasks.map(t=>taskRow(t)).join("")||`<div class="empty small-empty"><strong>Nothing needs doing</strong>The automatic messages run quietly in the background.</div>`}</div>`;body.append(section);wireTaskActions(section);$("#journey-add-task",section).onclick=()=>showModal("Add something to do",`<label class="full">What needs doing?<input id="task-title" required placeholder="Call the venue or check a detail"></label><label class="full">When is it due?<input id="task-due" type="datetime-local"></label>`,async()=>{await api(`/api/bookings/${r.id}/tasks`,{method:"POST",body:JSON.stringify({title:value("#task-title").trim(),due_at:nullable(value("#task-due"))})});closeModal();toast("Added to things to do");openDrawer(r.id,"Journey")},"This is a private reminder for you. It does not email the client.")}
function renderRecordDocuments(r,body){
  const legacy=r.documents.filter(d=>d.source_system==="studio_ninja"),current=r.documents.filter(d=>d.source_system!=="studio_ninja");
  body.innerHTML=`${legacy.length?`<section class="legacy-documents"><h3>Original Studio Ninja documents</h3><p>These source PDFs are permanently retained with the booking.</p><div class="document-list">${legacy.map(d=>documentRow(d)).join("")}</div></section>`:""}<form id="upload-form" class="upload-box"><div><strong>Upload a new document</strong><small>PDF, DOCX, JPEG or PNG · maximum 25MB</small></div><select id="document-category"><option value="contract">Contract</option><option value="booking_form">Booking form</option><option value="questionnaire">Questionnaire</option><option value="quote">Quote</option><option value="attachment">Other attachment</option></select><input id="document-file" type="file" accept=".pdf,.docx,.jpg,.jpeg,.png" required><button class="primary" type="submit">Upload</button></form><h3 class="section-title">BookingSystem2026 documents</h3><div class="document-list">${current.map(d=>documentRow(d)).join("")||`<div class="empty small-empty"><strong>No new documents uploaded</strong>Files added here stay securely attached to this record.</div>`}</div>`;
  $("#upload-form").onsubmit=async e=>{e.preventDefault();const file=$("#document-file").files[0];if(!file)return;const data=new FormData();data.append("file",file);await api(`/api/bookings/${r.id}/documents?category=${encodeURIComponent(value("#document-category"))}`,{method:"POST",body:data});toast("Document uploaded");openDrawer(r.id,"Documents")};
  wireDocumentActions(body);
}
function renderFinance(r,body){
  const invoiced=r.invoices.reduce((s,i)=>s+i.total,0),paid=r.invoices.reduce((s,i)=>s+i.paid,0);
  body.innerHTML=`<section class="summary"><div><small>QUOTED</small><strong>${money(r.quoted_total)}</strong></div><div><small>INVOICED</small><strong>${money(invoiced)}</strong></div><div><small>PAID</small><strong>${money(paid)}</strong></div></section><div class="section-actions"><div><h3>Invoices & bank transfers</h3><p>Independent ${r.brand==="wbm"?"WBM":"Ivory Digital"} numbering</p></div><button id="new-invoice" class="primary">＋ New invoice</button></div><div class="invoice-cards">${r.invoices.map(i=>`<article class="invoice-card"><header><div><strong>${esc(i.number)}</strong><span class="status ${statusClass(i.status)}">${esc(statusText(i.status))}</span>${i.legacy_number?`<small class="legacy-ref">Studio Ninja ${esc(i.legacy_number)}</small>`:""}</div><div class="file-actions"><a href="/api/invoices/${i.id}/pdf">Invoice PDF</a>${i.paid>0?`<a href="/api/invoices/${i.id}/receipt.pdf">Receipt</a>`:""}</div></header><dl><dt>Total</dt><dd>${money(i.total)}</dd><dt>Paid</dt><dd>${money(i.paid)}</dd><dt>Balance</dt><dd><strong>${money(i.balance)}</strong></dd></dl>${i.description?`<p>${esc(i.description)}</p>`:""}${i.payment_schedule?.length?`<div class="legacy-schedule"><strong>Original payment schedule</strong>${i.payment_schedule.map(item=>`<div><span>${esc(item.label||"Scheduled payment")}<small>${item.due_date?esc(fmtDate(item.due_date)):"No date"} · ${esc(statusText(item.status||"scheduled"))}</small></span><b>${money(item.amount)}</b></div>`).join("")}</div>`:""}<div class="payments">${i.payments.map(p=>`<div data-payment="${p.id}"><span><strong>${money(p.amount)}</strong><small>${esc(fmtDate(p.paid_date))} · ${esc(statusText(p.payment_type))}${p.legacy_source?" · imported":""}</small></span>${p.legacy_source?`<em class="retained-chip">Retained</em>`:`<button class="mini danger-text" data-action="delete-payment">Delete</button>`}</div>`).join("")}</div>${i.balance>0?`<button class="secondary full" data-payment-invoice="${i.id}" data-balance="${i.balance}">Record bank transfer</button>`:""}</article>`).join("")||`<div class="empty small-empty"><strong>No invoices yet</strong>Create the first branded invoice above.</div>`}</div>`;
  $("#new-invoice").onclick=()=>newInvoice(r);
  $$('[data-payment-invoice]',body).forEach(b=>b.onclick=()=>recordPayment(r,b.dataset.paymentInvoice,Number(b.dataset.balance)));
  $$('[data-action="delete-payment"]',body).forEach(b=>b.onclick=async()=>{if(!confirm("Remove this payment entry?"))return;await api(`/api/payments/${b.closest("[data-payment]").dataset.payment}`,{method:"DELETE"});toast("Payment removed");openDrawer(r.id,"Finance")});
}
function newInvoice(r){showModal("Create branded invoice",`<label>Total<input id="invoice-total" type="number" min="0.01" step="0.01" value="${Number(r.quoted_total||0)}" required></label><label>Already paid<input id="invoice-paid" type="number" min="0" step="0.01" value="${Number(r.deposit_amount||0)}"></label><label>Issue date<input id="invoice-date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Due date<input id="invoice-due" type="date" value="${attr(r.balance_due_date||"")}"></label><label class="full">Description<textarea id="invoice-description" rows="3">${esc(r.package_name||r.venue_or_project||"")}</textarea></label><label class="full">Invoice notes<textarea id="invoice-notes" rows="2" placeholder="Optional"></textarea></label>`,async()=>{const i=await api(`/api/bookings/${r.id}/invoices`,{method:"POST",body:JSON.stringify({total:Number(value("#invoice-total")),paid:Number(value("#invoice-paid")||0),issue_date:value("#invoice-date"),due_date:nullable(value("#invoice-due")),supply_date:r.event_date,description:nullable(value("#invoice-description")),notes:nullable(value("#invoice-notes"))})});closeModal();await refresh();toast(`Invoice ${i.number} created`);openDrawer(r.id,"Finance")},`The next number will use the independent ${r.brand==="wbm"?"WBM":"ID"} counter.`)}
function recordPayment(r,invoiceId,balance){showModal("Record bank transfer",`<label>Amount<input id="payment-amount" type="number" min="0.01" max="${balance}" step="0.01" value="${balance}" required></label><label>Date received<input id="payment-date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label class="full">Reference<input id="payment-reference" placeholder="Bank reference or invoice number"></label><label class="full">Notes<textarea id="payment-notes" rows="2"></textarea></label>`,async()=>{const result=await api(`/api/invoices/${invoiceId}/payments`,{method:"POST",body:JSON.stringify({amount:Number(value("#payment-amount")),paid_date:value("#payment-date"),payment_type:"bank_transfer",reference:nullable(value("#payment-reference")),notes:nullable(value("#payment-notes"))})});closeModal();await refresh();if(result.payment_email_sent)toast("Bank transfer recorded and confirmation emailed");else if(result.payment_email_paused)toast("Bank transfer recorded; client email remains safely paused");else if(result.payment_email_error)toast(`Payment recorded, but the email was not sent: ${result.payment_email_error}`,"error");else toast("Bank transfer recorded");openDrawer(r.id,"Finance")})}
async function toggleArchive(r){const action=r.archived?"restore":"archive";if(!r.archived&&!confirm("Archive this record? You can restore it from the Archived filter."))return;try{await api(`/api/bookings/${r.id}/${action}`,{method:"POST"});closeDrawer();await refresh();toast(r.archived?"Record restored":"Record archived");render()}catch(e){toast(e.message,"error")}}
function showError(e){$("#content").innerHTML=`<div class="panel empty"><strong>Something went wrong</strong>${esc(e.message)}</div>`}

init();
